# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::ReservationDerivation do
  # "Make every derived value repeatable: a reservation's `operation_id` is a UUIDv5 of company, entry and invoice, and timestamps are a capture time passed in."
  it "derives byte-identical reservations and corrections when run twice with the same capture time" do
    captured_at = Time.utc(2026, 10, 25, 12, 0, 0)
    row = ->(id, locked) { { "id" => id, "company_id" => 1, "version" => 0, "locked" => locked, "created_at" => Time.utc(2026, 1, 1), "updated_at" => Time.utc(2026, 1, 2) } }
    entry = ->(id, locked) { { id:, locked:, company_id: 1, join_company_id: 1, row: row.call(id, locked) } }
    derive = lambda do |invoice_id_for_active|
      described_class.derive(
        company_id: 1,
        entries: [entry.call(1, true), entry.call(2, false)],
        links: [
          { entry_id: 1, invoice_id: invoice_id_for_active, invoice_company_id: 1, draft: false, discarded: false },
          { entry_id: 2, invoice_id: 20, invoice_company_id: 1, draft: false, discarded: false }
        ],
        invoice_numbers: { 10 => "INV-10", 11 => "INV-11", 20 => "INV-20" },
        recorded_invoices: { "INV-20" => { "entry_ids" => [2], "disposition" => "reserve" } },
        generation: 7,
        captured_at:
      )
    end

    first = derive.call(10)
    second = derive.call(10)

    expect(first).to eq(second)
    expect(first[:refusals]).to eq([])
    expect(first[:reservations].size).to eq(2)
    expect(first[:reservations].map { |reservation| reservation["created_at"] }).to all(eq(captured_at))
    expect(first[:reservations].map { |reservation| reservation["operation_id"] }).to all(match(/\A\h{8}-\h{4}-5\h{3}-[89ab]\h{3}-\h{12}\z/))
    expect(first[:reservations].map { |reservation| reservation["operation_id"] }.uniq.size).to eq(2)

    other_invoice = derive.call(11)[:reservations].find { |reservation| reservation["entry_id"] == 1 }
    same_invoice = first[:reservations].find { |reservation| reservation["entry_id"] == 1 }
    expect(other_invoice["operation_id"]).not_to eq(same_invoice["operation_id"])
  end
end

# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::ReservationDerivation do
  # "A corrected entry is one whose reservation state differs from its legacy `locked` value."
  # "The correction list carries one snapshot per corrected entry, at version 1 and the generation passed in."
  it "lists exactly one correction at version 1 and the passed generation only for entries whose reservation state differs from locked" do
    captured_at = Time.utc(2026, 10, 25, 12, 0, 0)
    stored_created = Time.utc(2026, 1, 1, 9, 0, 0)
    stored_updated = Time.utc(2026, 1, 2, 9, 0, 0)
    row = ->(id, locked) { { "id" => id, "company_id" => 1, "version" => 0, "locked" => locked, "created_at" => stored_created, "updated_at" => stored_updated } }
    entry = ->(id, locked) { { id:, locked:, company_id: 1, join_company_id: 1, row: row.call(id, locked) } }

    result = described_class.derive(
      company_id: 1,
      entries: [entry.call(1, true), entry.call(2, true), entry.call(3, false), entry.call(4, true)],
      links: [
        { entry_id: 1, invoice_id: 10, invoice_company_id: 1, draft: false, discarded: false },
        { entry_id: 2, invoice_id: 30, invoice_company_id: 1, draft: true, discarded: true },
        { entry_id: 3, invoice_id: 20, invoice_company_id: 1, draft: false, discarded: false },
        { entry_id: 4, invoice_id: 40, invoice_company_id: 1, draft: false, discarded: true }
      ],
      invoice_numbers: { 10 => "INV-10", 20 => "INV-20", 30 => "INV-30", 40 => "INV-40" },
      recorded_invoices: { "INV-20" => { "entry_ids" => [3], "disposition" => "reserve" } },
      generation: 7,
      captured_at:
    )

    expect(result[:refusals]).to eq([])
    expect(result[:corrections].map { |correction| correction["entry_id"] }).to eq([2, 3])
    result[:corrections].each do |correction|
      expect(correction["company_id"]).to eq(1)
      expect(correction["generation"]).to eq(7)
      expect(correction["captured_at"]).to eq(captured_at)
      expect(correction["snapshot"]["version"]).to eq(1)
      expect(correction["snapshot"]["created_at"]).to eq(stored_created)
      expect(correction["snapshot"]["updated_at"]).to eq(stored_updated)
    end
    released, reserved = result[:corrections]
    expect(released["snapshot"]["locked"]).to be(false)
    expect(reserved["snapshot"]["locked"]).to be(true)

    owners = result[:reservations].to_h { |reservation| [reservation["entry_id"], [reservation["invoice_id"], reservation["state"], reservation["disposition"]]] }
    expect(owners).to eq(1 => [10, "committed", "active"], 3 => [20, "committed", "active"], 4 => [40, "committed", "retained"])
  end
end

# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::ReservationDerivation do
  # "Cutover proceeds only when the orphan, conflict and unlocked-link lists are empty, or every item has a recorded disposition."
  # "Refuse, never guess, when a number is missing, matches no invoice of that company, or would link an entry to another company's invoice."
  it "refuses a conflict, an unrecorded unlocked link and a recorded number that is not one of the company's invoices" do
    captured_at = Time.utc(2026, 10, 25, 12, 0, 0)
    entry = ->(id, locked) { { id:, locked:, company_id: 1, join_company_id: 1, row: { "id" => id, "company_id" => 1, "locked" => locked, "version" => 0 } } }
    link = ->(entry_id, invoice_id) { { entry_id:, invoice_id:, invoice_company_id: 1, draft: false, discarded: false } }
    derive = ->(entries:, links:, recorded:) {
      described_class.derive(
        company_id: 1, entries:, links:, invoice_numbers: { 11 => "INV-11", 12 => "INV-12" },
        recorded_invoices: recorded, generation: 7, captured_at:
      )
    }

    conflict = derive.call(entries: [entry.call(101, true)], links: [link.call(101, 11), link.call(101, 12)], recorded: {})
    expect(conflict[:refusals]).not_to be_empty
    expect(conflict[:refusals].join("\n")).to include("101")
    expect(conflict[:reservations].pluck("entry_id")).not_to include(101)

    unrecorded = derive.call(entries: [entry.call(102, false)], links: [link.call(102, 11)], recorded: {})
    expect(unrecorded[:refusals]).not_to be_empty
    expect(unrecorded[:refusals].join("\n")).to include("102")
    expect(unrecorded[:reservations]).to be_empty

    # INV-99 is not an invoice of company 1, so it must never resolve, even if another company has it.
    foreign_number = derive.call(
      entries: [entry.call(103, false)], links: [link.call(103, 11)],
      recorded: { "INV-99" => { "entry_ids" => [103], "disposition" => "reserve" } }
    )
    expect(foreign_number[:refusals]).not_to be_empty
    expect(foreign_number[:refusals].join("\n")).to include("INV-99")
    expect(foreign_number[:reservations]).to be_empty
  end
end
